 for(const selectedSubject of order){const pool=all.filter(q=>q.subject===selectedSubject);
  for(let i=0;i<pool.length;i++){const q=pool[(start+i)%pool.length];if(!excluded.has(q.pairKey)&&!excluded.has(q.contentKey))return {...structuredClone(q),relationship,regionalRotation:true,contentVersion:REGIONAL_LIFESTYLE_BANK.version,lifestyleBankId:q.id};}
 }
